class LiveServerThreadedWSGIServer(ThreadedWSGIServer):
    """
    ThreadedWSGIServer that shares the test database connections with its
    request threads and closes them when each request is finished.
    """
    def __init__(self, *args, connections_override=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.connections_override = connections_override

    def process_request_thread(self, request, client_address):
        if self.connections_override:
            # Use the connections provided by the main thread.
            for alias, conn in self.connections_override.items():
                connections[alias] = conn
        super().process_request_thread(request, client_address)

    def close_request(self, request):
        connections.close_all()
        super().close_request(request)


